  <div class="flex gap-1 p-1">
    <button
      v-for="shift in availableShifts"
      :key="shift"
      :class="getShiftButtonClass(shift)"
      :disabled="readonly"
      @click="handleSelect(shift)"
    >
      {{ shift }}
    </button>
  </div>
